E["npc:ayessa-dawnsinger"] = {t="npc",n="Ayessa Dawnsinger",z="zephras",s="Ayessa Dawnsinger is a Skyborne leader found in Valanaar on Zephras Isle. She leads the Windshapers, guiding the Skyborne aligned with the Horde through their trials and politics.",h="Ayessa Dawnsinger is a Skyborne leader found in Valanaar on Zephras Isle.",sec={{t="Leader of the Windshapers",b="Standing within the settlement of Valanaar on Zephras Isle, Ayessa Dawnsinger serves as the paramount guide for the Windshapers—the faction of Skyborne aligned with the Horde. From this vantage, she directs critical efforts across the island, managing external threats, internal fractures, and the overarching survival of her people as they navigate alliances in Kalimdor and beyond.",sp=0},{t="The Struggle for Zephras",b="Ayessa plays a pivotal role in resolving conflicts on the isle, dispatching trusted champions to address rogue constructs, hostile figures like Lorthuna, and the grander fate awaiting the Skyborne. Her authority steers the Windshapers through tense political and physical confrontations, ensuring their voice and strength remain respected within the Horde.",sp=1}},faq={{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger is a prominent Skyborne figure who leads the Windshapers, the faction of Skyborne allied with the Horde on Zephras Isle.",al={"ayessa lore","who is ayessa","ayessa dawnsinger background"}},{q="Where can Ayessa Dawnsinger be found?",a="She is located in the settlement of Valanaar on Zephras Isle.",al={"where is ayessa","ayessa location","ayessa dawnsinger map"}},{q="What are the Windshapers?",a="The Windshapers are the Skyborne faction aligned with the Horde, guided by Ayessa Dawnsinger from their base in Valanaar.",al={"windshapers faction","who are windshapers"}},{q="What is Ayessa's role in local quests?",a="Ayessa issues multiple vital quests dealing with the island's defense, including investigating rogue constructs, confronting Lorthuna, and shaping the future fate of Zephras.",al={"ayessa quests","ayessa questline"}}},ang={["faction:Horde"]="For the Horde, Ayessa Dawnsinger represents their primary Skyborne partnership, anchoring their presence and diplomatic ties on Zephras Isle.",["race:Skyborne"]="As the leader of the Windshapers, Ayessa embodies the vision of Skyborne who choose solidarity with the Horde to secure their future."},kw={"ayessa","dawnsinger","horde","skyborne","valanaar","windshapers","zephras"},rel={"topic:skyborne","zone:zephras","topic:horde","quest:93746"},src={"Ayessa Dawnsinger"}}
E["npc:halaan-hawk-eye"] = {t="npc",n="Halaan Hawk-Eye",z="zephras",s="Halaan Hawk-Eye is a Skyborne lookout stationed atop the watchtower of Thendal Village on Zephras Isle. Lacking both magical sensitivity and the mystic skysight of his peers, he relies instead on keen mundane vision to monitor the surrounding island. From his perch, he tracks the distant anchor pylons and warns visitors of their faltering arcane stability.",h="Halaan Hawk-Eye is a Skyborne lookout stationed atop the watchtower of Thendal Village on Zephras Isle.",sec={{t="A Watchman Without Magic",b="Perched high above Thendal Village, Halaan Hawk-Eye serves his people without the gifts common to many Skyborne. He cannot draw upon the arcane power flowing through the ley lines beneath Zephras Isle, nor can he gaze between worlds through the mystical skysight. Instead, Halaan relies entirely on his sharp natural senses. From his vantage point on the watchtower, he scans the horizon to observe the island's anchor pylons, calling attention to their increasingly volatile and inconsistent arcane energies.",sp=0}},faq={{q="Who is Halaan Hawk-Eye?",a="Halaan Hawk-Eye is a Skyborne sentry stationed atop the watchtower overlooking Thendal Village on Zephras Isle. He observes the surrounding land and alerts adventurers to the erratic magic afflicting the island's anchor pylons.",al={"halaan hawkeye","who is halaan","thendal watchtower npc"}},{q="What makes Halaan different from other Skyborne?",a="Unlike many among his kin, Halaan possesses neither the mystical skysight that pierces the veil between worlds nor an innate ability to harness the subterranean ley lines of Zephras Isle. He relies on his keen physical eyesight and natural observation instead.",al={"halaan abilities","can halaan use magic","halaan skysight"}},{q="Why is Halaan worried about the anchor pylons?",a="Halaan keeps watch over the distant anchor pylons and has noticed that their magical output has turned erratic and inconsistent, posing an unknown risk to the stability of Zephras Isle.",al={"what is wrong with the pylons","anchors of zephras problem"}},{q="Where can I find Halaan Hawk-Eye?",a="He can be found standing atop the wooden watchtower in Thendal Village on Zephras Isle, peering out over the horizon.",al={"where is halaan","halaan location"}}},ang={["race:Skyborne"]="Halaan represents those among the Skyborne who lack natural affinity for ley line manipulation or the skysight, serving their community through steadfast vigilance and martial duty instead."},kw={"anchor pylon","halaan","hawk-eye","skyborne","skysight","thendal village","zephras isle"},rel={"quest:94414","zone:zephras","topic:skyborne"},src={"Halaan Hawk-Eye"}}
E["npc:rorian-the-dayseeker"] = {t="npc",n="Rorian the Dayseeker",z="zephras",s="Rorian the Dayseeker is an elder Skyborne figure situated in Thendal Village on Zephras Isle. He oversees the initiation of young fledglings as they discover their calling, step into maturity, and attune themselves to the natural elements of their homeland. Under his watchful guidance, newcomers learn the fundamentals of survival, tradition, and service to their community.",h="Rorian the Dayseeker is an elder Skyborne figure situated in Thendal Village on Zephras Isle.",sec={{t="Elder of Thendal Village",b="Within the serene confines of Thendal Village on Zephras Isle, Rorian the Dayseeker stands as one of the primary mentors for the fledgling Skyborne. Revered for his experience and calm wisdom, Rorian directs youth during their crucial transition into adulthood. It is under his instruction that initiates undertake their traditional rite of passage, marking their readiness to defend and support their island home.",sp=0},{t="Guiding the New Callings",b="Beyond fundamental trials, Rorian points promising initiates toward specialized paths suited to their talents. Whether an aspiring warrior, hunter, rogue, mage, shaman, or druid, fledglings are directed by Rorian to dedicated trainers across the isle. He also alerts them to elemental disturbances disrupting the island's harmony, instilling an enduring duty to preserve balance across the windswept heights.",sp=0}},faq={{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder Skyborne leader found in Thendal Village on Zephras Isle. He serves as the primary mentor for novice adventurers and fledgling Skyborne embarking on their early trials.",al={"who is rorian","rorian role","what does rorian do"}},{q="Where can Rorian the Dayseeker be found?",a="He is located in Thendal Village, the starting settlement for the Skyborne on Zephras Isle.",al={"where is rorian","rorian location","find rorian"}},{q="What is Rorian's role in the Skyborne coming of age?",a="Rorian oversees the initial rites of passage that mark a fledgling's transition into adulthood. He tests their mettle and attunement to island life before directing them outward to serve the wider settlement.",al={"rorian coming of age","skyborne trial mentor"}},{q="How does Rorian direct new trainees into their classes?",a="Once a novice proves their worth, Rorian advises them on where to pursue advanced training, offering guidance toward the paths of the warrior, hunter, rogue, mage, shaman, or druid.",al={"class quests rorian","choosing a class with rorian"}},{q="Why does Rorian send adventurers to deal with elementals?",a="The natural balance around Zephras Isle is vulnerable to agitation. Rorian tasks capable initiates with investigating and calming elemental unrest so that Thendal Village and the surrounding wildlands remain in harmony.",al={"elemental unrest rorian","why fight elementals zephras"}},{q="Who is Aetheen of the Gales?",a="Aetheen of the Gales is an individual on Zephras Isle to whom Rorian directs fledglings as they progress through their island responsibilities and training.",al={"aetheen rorian","aetheen of the gales"}}},ang={["race:Skyborne"]="For every fledgling Skyborne, Rorian the Dayseeker represents the first threshold of duty and tradition, guiding your transition into adulthood in Thendal Village.",["class:Warrior"]="Rorian recognizes the physical dedication of aspiring fighters, pointing aspiring warriors toward the mentors who teach discipline on the battlefield.",["class:Mage"]="Novice arcanists find an understanding guide in Rorian, who directs budding scholars of the arcane toward teachers capable of honing raw magical potential.",["class:Shaman"]="Rorian places heavy emphasis on the island's harmony, dispatching fledglings to soothe agitated elementals and connect with ancestral traditions."},kw={"dayseeker","fledgling","mentor","rorian","skyborne","thendal","zephras"},rel={"zone:zephras","topic:skyborne","quest:92460","quest:92461","quest:92464","quest:92469","quest:92471","quest:92474"},src={"Rorian the Dayseeker"}}
E["npc:ventaari-brightwish"] = {t="npc",n="Ventaari Brightwish",z="zephras",s="Ventaari Brightwish is a Skyborne resident of Thendal Village on Zephras Isle. She greets travelers from across Azeroth and offers the quest The Gift of Skysight.",h="Ventaari Brightwish is a Skyborne resident of Thendal Village on Zephras Isle.",sec={{t="A Dweller of Thendal Village",b="Residing in Thendal Village upon the soaring cliffs of Zephras Isle, Ventaari Brightwish is one of the local Skyborne. While she shares a surname with Belathaan Brightwish, her own duties center around aiding newcomers who find their way to the village, extending hospitality to both the Alliance and the Horde as she initiates visitors into the traditions of her people through tasks like The Gift of Skysight.",sp=0}},faq={{q="Who is Ventaari Brightwish?",a="Ventaari Brightwish is a Skyborne NPC stationed in Thendal Village on Zephras Isle. She interacts with visitors and offers the quest The Gift of Skysight.",al={"ventaari","who is ventaari","ventaari brightwish"}},{q="Where can I find Ventaari Brightwish?",a="She can be found in Thendal Village, located on the island of Zephras Isle.",al={"ventaari location","where is ventaari","thendal village ventaari"}},{q="Is Ventaari hostile to the Horde or Alliance?",a="No. Ventaari Brightwish is neutral and will speak with adventurers from both the Alliance and the Horde.",al={"ventaari faction","is ventaari friendly","can horde talk to ventaari"}},{q="Is Ventaari related to Belathaan Brightwish?",a="She shares the surname Brightwish and is believed to be a relative of Belathaan Brightwish.",al={"belathaan brightwish relative","brightwish family"}}},ang={["race:Skyborne"]="As a member of the Skyborne in Thendal Village, Ventaari Brightwish helps visitors connect with the culture and ways of Zephras Isle."},kw={"brightwish","skyborne","skysight","thendal village","ventaari","zephras isle"},rel={"zone:zephras","quest:92598","topic:skyborne","topic:alliance","topic:horde"},src={"Ventaari Brightwish"}}
E["quest:92460"] = {t="quest",n="Coming of Age",z="zephras",s="Coming of Age marks the initial rite of passage for young Skyborne taking their first steps beyond Thendal Village on Zephras Isle. Guided by Ailee Farheart, novices report to village leader Rorian the Dayseeker to receive an ancestral relic and formally pledge their aid to the shen'dorei.",h="Coming of Age marks the initial rite of passage for young Skyborne taking their first steps beyond Thendal...",sec={{t="A Rite of Passage",b="For every young Skyborne coming into adulthood, the journey begins in Thendal Village. Guided forward by Ailee Farheart, fledglings make their way just west to the greatfather tree where the village elder awaits. Passing into maturity among the shen'dorei is not merely a social milestone, but a ceremonial commitment to serve their community amid rising local troubles.",sp=0},{t="The Ancestral Relic",b="At the entrance of the greatfather tree, Rorian the Dayseeker presides over the ceremony. He formally bestows an ancestral relic upon the initiate—an heirloom passed through generations of shen'dorei. Borne by many who came before, the relic serves as a lasting token of the winds of home, destined to return to the people only when its bearer's ashes are scattered to the breeze.",sp=0}},faq={{q="What is the purpose of the Coming of Age ceremony?",a="It serves as the formal transition into adulthood for young Skyborne, officially welcoming them into active service for the shen'dorei and granting them an ancestral heirloom.",al={"why coming of age","coming of age purpose","skyborne rite of passage"}},{q="Who initiates the quest?",a="Ailee Farheart, who watches over the village novices in Thendal Village on Zephras Isle, welcomes you and sends you to meet the village leadership.",al={"who gives coming of age","where does coming of age start","ailee farheart location"}},{q="Who do you report to for the ritual?",a="Rorian the Dayseeker, the village leader of Thendal Village, who stands at the entrance to the greatfather tree just west of the settlement.",al={"who is rorian","where is rorian","rorian the dayseeker location"}},{q="What relic is bestowed during the ceremony?",a="Rorian presents an inherited coming-of-age relic that has been carried by generations of shen'dorei before you. Tradition dictates it remains with you until death, when it passes to the next generation.",al={"what is the relic","skyborne relic","what do you get"}},{q="What does 'shen'dorei' mean in this context?",a="Rorian uses 'shen'dorei' to refer to the Skyborne, evoking their complex history, shared trials, and enduring identity on Zephras Isle.",al={"who are the shendorei","shendorei meaning","skyborne shendorei"}},{q="Where does your journey lead immediately after this?",a="After completing your rite of passage, Rorian directs your attention to local matters threatening the island, beginning with quests such as Harmony in Balance and Infestation Investigation.",al={"what quest is next","next steps after coming of age","after rorian"}}},ang={["race:Skyborne"]="This rite of passage defines your entry into adulthood, granting you a sacred family heirloom to carry wherever the winds blow."},kw={"ailee farheart","coming of age","rorian the dayseeker","shen'dorei","skyborne","thendal grove","thendal village","zephras isle"},rel={"zone:zephras","npc:rorian-the-dayseeker","topic:skyborne"},m={start="Ailee Farheart",["end"]="Rorian the Dayseeker",level="1",id=92460},src={"Coming of Age (Forever)"},fv=true}
E["quest:92461"] = {t="quest",n="Harmony in Balance",z="zephras",s="Harmony in Balance is an early rite of duty given to fledgling adventurers on Zephras Isle by Rorian the Dayseeker. It tasks the player with culling juvenile vuldren in Thendal Grove to preserve the natural equilibrium of the island. Through this mundane necessity, novices learn how sensitive local beasts are to the shifting magical currents around them.",h="Harmony in Balance is an early rite of duty given to fledgling adventurers on Zephras Isle by Rorian the...",sec={{t="Tending the Grove",b="Even in an era defined by uncertain futures and mounting peril, daily survival on Zephras Isle requires humble diligence. In Thendal Grove, the local vuldren population has grown at an unsustainable rate, threatening the delicate environmental harmony that sustains the island's wildlife. Rorian the Dayseeker assigns young protectors the sober task of thinning their numbers to avert widespread ecological strain.",sp=0},{t="Winds of Unrest",b="While culling wild beasts may appear to be ordinary gamekeeping, the vuldren's surge reflects deeper concerns. Though typically docile creatures, the wildlife of Zephras is attuned to the island's atmosphere and reacts sharply when the magic carried on the winds falls out of balance. Correcting imbalances early prevents docile creatures from degenerating into unpredictable and dangerous pests.",sp=0}},faq={{q="Why do the vuldren need to be culled?",a="The vuldren population in Thendal Grove has surged beyond sustainable numbers. If left unchecked, they risk exhausting local resources and disrupting the delicate ecological balance that sustains the grove's other inhabitants.",al={"why kill vuldren","vuldren overpopulation","thendal grove vuldren"}},{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder guide and mentor on Zephras Isle. He oversees the training of young adventurers, reminding them that protecting their home requires attentiveness to both grand crises and everyday ecological stewardship.",al={"rorian lore","who is rorian"}},{q="What makes the vuldren act up?",a="Vuldren are normally docile creatures, but the native fauna of Zephras can sense when the ambient magic woven into the island's winds is drifting out of balance, prompting sudden shifts in behavior.",al={"why are vuldren aggressive","vuldren behavior"}},{q="Where does this task take place?",a="The task is carried out in Thendal Grove, an area lying just east and southeast of the settlement on Zephras Isle.",al={"thendal grove location","where is thendal grove"}},{q="What lesson is Rorian trying to teach?",a="Rorian teaches that protecting one's homeland often demands difficult, unsavory measures. Taking a firm guiding hand to restore natural order is an essential responsibility for any burgeoning guardian.",al={"rorian lesson","meaning of harmony in balance"}},{q="What should be done while hunting the vuldren?",a="Elatrell Featherlight nearby asks adventurers to look into a swarm of pesky cirrusflies, making it practical to investigate the insect infestation in the grove at the same time.",al={"other quests nearby","infestation investigation"}}},ang={["class:Druid"]="The mandate to cull overpopulated vuldren resonates strongly with druidic philosophy, where culling is sometimes required to preserve the larger health of the ecosystem.",["class:Hunter"]="Managing herd numbers and observing how native beasts respond to environmental disturbances is foundational training for any tracker in Thendal Grove."},kw={"harmony in balance","juvenile vuldren","rorian the dayseeker","thendal grove","vuldren","zephras","zephras isle"},rel={"npc:rorian-the-dayseeker","zone:zephras","quest:92462"},m={start="Rorian the Dayseeker",level="1",id=92461},src={"Harmony in Balance"},fv=true}
E["quest:92462"] = {t="quest",n="Infestation Investigation",z="zephras",s="Infestation Investigation is an early task given to young adventurers stepping out into Thendal Grove on Zephras Isle. Ranger Elatrell Featherlight orders a cull of pesky cirrusflies that have begun swarming the eastern groves. Left unchecked, the fast-breeding insects threaten to destabilize the peaceful grove and endanger local settlements.",h="Infestation Investigation is an early task given to young adventurers stepping out into Thendal Grove on...",sec={{t="A Swarm in the Canopy",b="Thendal Grove has long maintained a delicate balance, but recent reports by local rangers indicate a sudden population surge of pesky cirrusflies on the eastern edge of the woods. While individual cirrusflies are minor pests, their swarms quickly turn aggressive and destructive when numbers balloon. Ranger Elatrell Featherlight wastes no time dispatching capable youth to cull the flying insects before their presence completely overwhelms the grove.",sp=0},{t="Early Steps of Service",b="Following their initial coming of age, young defenders are thrust directly into the practical upkeep of Zephras Isle. Clearing out pests might seem like menial labor, but keeping the woodlands safe from creeping wildlife outbreaks is vital to safeguarding the settlements nearby. The sheer abundance of entrails and insects clinging to returning hunters proves that the swarm's scale is far worse than initially feared.",sp=0}},faq={{q="What is a cirrusfly?",a="Cirrusflies are winged insect pests native to the lush environments of Zephras Isle. Though small on their own, they multiply rapidly and can quickly form hazardous swarms if their numbers are left unchecked in places like Thendal Grove.",al={"cirrusfly","cirrusflies","what are cirrusflies"}},{q="Who gives the quest Infestation Investigation?",a="The task is assigned by Elatrell Featherlight, a ranger stationed in Thendal Grove tasked with keeping the local wildlife and surrounding woods under control.",al={"quest giver","who starts it","elatrell featherlight"}},{q="Where are the cirrusflies located?",a="The pesky cirrusflies cluster toward the eastern and southeastern reaches of Thendal Grove on Zephras Isle, buzzing through the foliage alongside young vuldren.",al={"where to find flies","cirrusfly location","thendal grove flies"}},{q="Why is culling the cirrusflies important?",a="While an isolated insect poses little danger, cirrusfly swarms can quickly grow dense enough to threaten travelers, deplete local plants, and disturb the peaceful balance of Thendal Grove.",al={"why kill flies","why cull cirrusflies","cirrusfly threat"}},{q="What comes after Infestation Investigation?",a="After thinning the swarm and reporting back to Elatrell Featherlight, adventurers are directed toward the heart of the infestation to confront the Cirrusfly Queen.",al={"next quest","what next","investigation follow up"},sp=1},{q="Where does this quest fit into the early journey on Zephras?",a="The quest is offered immediately after completing the Coming of Age trial, serving as one of the first combat assignments given to newly recognized defenders of Zephras Isle.",al={"quest chain","when do i get this","level requirement"}}},ang={["class:Hunter"]="For budding marksmen and trackers, tracking small, darting cirrusflies among the trees offers valuable practice in leading fast-moving targets in dense cover.",["class:Druid"]="Preserving Thendal Grove means managing natural imbalances before aggressive swarms strip the woodland bare."},kw={"cirrusfly","elatrell featherlight","infestation","investigation","pesky cirrusfly","thendal grove","zephras"},rel={"quest:92463","zone:zephras"},m={start="Elatrell Featherlight",level="2",id=92462},src={"Infestation Investigation"},fv=true}
E["quest:92463"] = {t="quest",n="The Cirrusfly Queen",z="zephras",s="The Cirrusfly Queen is a hunt targeting the matriarch of the aggressive insect hive dwelling in Thendal Grove on Zephras Isle. Following early reconnaissance of the infestation, Elatrell Featherlight directs recruits into the heart of the grove to eliminate the queen and cull the swarm at its source. Ending her reign provides immediate relief to the local rangers working to keep the wilderness manageable.",h="The Cirrusfly Queen is a hunt targeting the matriarch of the aggressive insect hive dwelling in Thendal Grove...",sec={{t="Striking the Hive",b="Initial efforts against the cirrusflies revealed that simply swatting away stray worker drones would never curb the infestation spreading across Thendal Grove. Elatrell Featherlight tasks capable wanderers with penetrating deeper into the southeastern reaches of the grove where the main hive lies. There, the queen directs the colony under the vigilant protection of heavier soldier drones.",sp=0},{t="A Ranger's Burden",b="While common cirrusflies might seem like petty pests from a distance, their larger breeds pose a serious physical danger to anyone passing beneath the boughs of Zephras. By hunting down the matriarch and withstanding her guards, novices prove their martial mettle, earning high praise and a nod of respect from Featherlight's ranger cadre.",sp=0}},faq={{q="Where is the Cirrusfly Queen located?",a="The Cirrusfly Queen makes her nest in the southeastern corner of Thendal Grove on Zephras Isle, close to the heart of the insect hive.",al={"queen location","where is cirrusfly queen","find the queen"}},{q="Why is slaying the worker flies not enough?",a="Elatrell Featherlight recognizes that targeting wandering workers only thins the fringes of the swarm. As long as the queen lives, she will continue breeding aggressive soldiers and replenishing the hive, sustaining the threat to Thendal Grove.",al={"why kill the queen","culling the hive"}},{q="Who issues the hunt for the Cirrusfly Queen?",a="Elatrell Featherlight offers the task once initial reports from the forest confirm the severity of the cirrusfly presence.",al={"who gives this quest","quest giver queen"}},{q="What makes the queen more dangerous than regular cirrusflies?",a="Unlike the basic workers wandering the grove, the queen is surrounded by larger, far more aggressive soldier drones dedicated to defending her hive.",al={"queen danger","cirrusfly soldiers"}},{q="What quest precedes this assignment?",a="This mission directly follows the quest Infestation Investigation, which first established how pervasive the insect presence had become in the grove.",al={"prerequisite quest","what comes before"}},{q="What role does Elatrell Featherlight serve in the area?",a="Elatrell Featherlight oversees wilderness security on Zephras Isle, monitoring regional threats and mentoring new adventurers in woodland tracking and ranger duties.",al={"featherlight role","who is featherlight"}}},ang={["class:Hunter"]="Taking down an aggressive hive queen and outmaneuvering her defending soldiers offers an early trial in tracking and beast culling that earns direct praise from local rangers.",["race:Skyborne"]="Clearing out invasive swarms in Thendal Grove helps preserve the natural balance and safe travel routes across your homeland of Zephras Isle."},kw={"cirrusfly","elatrell featherlight","hive","queen","soldier","thendal grove","zephras"},rel={"quest:92462","zone:zephras"},m={start="Elatrell Featherlight",level="3",id=92463},src={"The Cirrusfly Queen"},fv=true}
E["quest:92464"] = {t="quest",n="Elemental Unrest",z="zephras",s="Elemental Unrest is an introductory task given by Rorian the Dayseeker on Zephras Isle. Following the departure of the island's sentient elemental benefactors, the lesser wind spirits near the Thendal Standing Stones have grown agitated and unpredictable. You are sent into Thendal Grove to find Rorian's apprentice, Yala Windwatcher, and discover what is unsettling the local breeze.",h="Elemental Unrest is an introductory task given by Rorian the Dayseeker on Zephras Isle.",sec={{t="A Change in the Wind",b="For generations, the people of Zephras lived alongside powerful, sentient wind spirits who guided and protected them. With those elemental benefactors gone, the island has drifted into persistent imbalance. The air is no longer tended by benevolent minds, leaving only simple sprites that reflect the volatile emotions and forces lingering across the landscape.",sp=0},{t="The Thendal Standing Stones",b="Northeast of Rorian's post, near the ancient Thendal Standing Stones, the air has grown sharply hostile. Because these lesser manifestations lack true self-awareness, their turbulence is not born of malice, but of reaction. Rorian sent his apprentice, Yala Windwatcher, to monitor their erratic behavior from the edge of the grove and deduce what unseen tension is disturbing them.",sp=0}},faq={{q="Why are the wind sprites agitated?",a="Unlike the island's former elemental benefactors, these wind sprites lack true self-awareness. They instinctively mirror the emotions, intentions, and ambient magical forces of creatures and events around them, turning turbulent whenever the local environment falls out of balance.",al={"why are elementals mad","wind unrest cause","sprites angry"}},{q="Who are the elemental benefactors Rorian mentions?",a="They were sentient, benevolent wind spirits who once coexisted with the inhabitants of Zephras. Since their departure, the island has suffered continuous unrest without their stabilizing influence.",al={"elemental benefactors","who left zephras","wind spirits zephras"}},{q="Where can I find Yala Windwatcher?",a="Yala Windwatcher is stationed in Thendal Grove to the northeast, overlooking the Thendal Standing Stones where the agitated wind sprites congregate.",al={"yala windwatcher location","where is yala","thendal grove apprentice"}},{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder guide on Zephras Isle who watches over the island's spiritual balance and studies the ongoing disturbances among the local elementals.",al={"who is rorian","rorian dayseeker"}},{q="What happens after finding Yala?",a="Speaking with Yala leads directly into investigating the true cause behind the turbulence at the standing stones, beginning with the task 'Agitators'.",al={"next quest","what comes after elemental unrest","yala follow up"}},{q="Are the wind sprites dangerous?",a="While simple in nature, their agitated state makes them erratic and defensive. They react aggressively to intrusion as long as the underlying disturbance persists.",al={"are sprites hostile","elemental danger"}}},ang={["class:Shaman"]="The wind spirits of Zephras reflect the island's emotional climate like a mirror, making this disturbance a clear warning sign of deeper environmental disruption.",["race:Skyborne"]="The departure of the elemental benefactors has left the winds unpredictable, demanding vigilance from those who depend on Zephras Isle's skies."},kw={"elemental unrest","rorian the dayseeker","thendal grove","thendal standing stones","wind sprites","yala windwatcher","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92465","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Yala Windwatcher",level="3",id=92464},src={"Elemental Unrest (quest)"},fv=true}
E["quest:92465"] = {t="quest",n="Agitators",z="zephras",s="Agitators is an early task on Zephras Isle issued by Yala Windwatcher. The aggressive Al'Aketh cult has pushed into Thendal Grove, agitating the peaceful native wind sprites into hostile elementals. Adventurers are sent to disperse the roiling winds and clear out the cultist converts threatening the area.",h="Agitators is an early task on Zephras Isle issued by Yala Windwatcher.",sec={{t="Disturbing the Grove",b="Thendal Grove has fallen under the shadow of the Al'Aketh cult. Known for their unsettling designs on Zephras Isle, the cultists have encroached on the grove and actively riled the delicate wind spirits dwelling there. Once peaceful sprites have turned violent, forming volatile roiling winds that threaten anyone passing through the region.",sp=0},{t="A Painful Necessity",b="Yala Windwatcher tasks passing champions with subduing both the enraged elementals and the Al'Aketh converts fomenting the unrest. While putting down the wind creatures restores a fragile calm to the grove, dealing with the cultists is a somber duty: Yala laments the shedding of shen'dorei blood among their own people, yet recognizes that the cult leaves little choice.",sp=0}},faq={{q="Who gives the quest Agitators?",a="Yala Windwatcher offers the quest in the vicinity of Thendal Grove on Zephras Isle.",al={"quest giver","who starts agitators","yala windwatcher"}},{q="What is the Al'Aketh cult doing in Thendal Grove?",a="The Al'Aketh cult has moved into the grove and agitated the native wind spirits, driving the peaceful creatures into a hostile, violent frenzy.",al={"what are cultists doing","why are alaketh here","alaketh convert purpose"}},{q="What are the Roiling Winds?",a="They are simple, native wind sprites of Zephras Isle that have been stirred up and corrupted into aggressive elemental whirlwinds by the Al'Aketh cultists.",al={"roiling winds","wind spirits","wind elementals in thendal grove"}},{q="Why is Yala Windwatcher saddened by killing the converts?",a="Yala laments having to shed shen'dorei blood in the grove, showing that the Al'Aketh converts belong to their own people who have fallen sway to dangerous cult teachings.",al={"why does yala regret killing","shedding shendorei blood","yala completion quote"}},{q="What quest follows Agitators?",a="After finishing Agitators for Yala Windwatcher, you are directed to continue your duties in the quest Return to Rorian.",al={"what quest is next","agitators follow up","where do i go after agitators"}},{q="Where does this conflict take place?",a="The conflict is centered in Thendal Grove, located on the island of Zephras Isle.",al={"agitators location","thendal grove zone","where is thendal grove"}}},ang={["class:Shaman"]="Witnessing natural wind sprites driven to violent frenzy by cultist meddling is an offense against elemental balance that demands intervention.",["class:Druid"]="The desecration of Thendal Grove's natural harmony by rogue cultists makes the defense of its native spirits an urgent priority."},kw={"agitators","al'aketh","al'aketh convert","roiling winds","shen'dorei","thendal grove","yala windwatcher","zephras isle"},rel={"zone:zephras","quest:92469"},m={start="Yala Windwatcher",level="3",id=92465},src={"Agitators"},fv=true}
E["quest:92469"] = {t="quest",n="Return to Rorian",z="zephras",s="Return to Rorian is a mission carrying urgent reports from the field back to Thendal Grove on Zephras Isle. After aiding Yala Windwatcher against encroaching forces, an adventurer is dispatched to inform Rorian the Dayseeker that the Al'Aketh cult has actively escalated their presence by disturbing the local wind spirits.",h="Return to Rorian is a mission carrying urgent reports from the field back to Thendal Grove on Zephras Isle.",sec={{t="A Dire Report",b="Following the disruption dealt to the agitators harassing Zephras Isle, Yala Windwatcher stays behind to mop up remaining hostiles while tasking you with an essential duty: delivering intelligence. Thendal Grove needs to know that the mysterious Al'Aketh are no longer operating purely in the shadows.",sp=0},{t="Escalation at the Standing Stones",b="Upon receiving the report, Rorian the Dayseeker admits that the leaders in Thendal Grove have watched the cult's movements from a distance for some time. However, the cultists agitating the native wind spirits near the standing stones marks a bold and troubling escalation that grove leadership can no longer afford to observe passively.",sp=1}},faq={{q="Who sends you to speak with Rorian?",a="Yala Windwatcher sends you to report to Rorian after you help suppress the hostile agitators threatening the local area.",al={"quest giver","who starts return to rorian","yala windwatcher"}},{q="Where is Rorian the Dayseeker located?",a="Rorian the Dayseeker can be found in Thendal Grove, the settlement where the grove's leaders oversee affairs on Zephras Isle.",al={"where is rorian","rorian location","thendal grove rorian"}},{q="Who are the Al'Aketh?",a="The Al'Aketh are a cult operating on Zephras Isle. While previously monitored quietly from afar, their recent actions agitating elemental wind spirits near the standing stones have turned them into an active threat.",al={"what is the cult","who are al'aketh","al'aketh cult"}},{q="Why was Rorian not surprised by the news?",a="Rorian and the grove leadership were already aware of the cult's movements across the island, though they had previously chosen to watch them quietly rather than confront them directly.",al={"did rorian know","rorian reaction","why unsurprising"}},{q="What happens after reporting back to Rorian?",a="After acknowledging your report and thanking you for aiding Thendal Grove, Rorian directs your attention toward handling the rising spiritual crisis in Aetheen of the Gales.",al={"next quest","what follows return to rorian","after return to rorian"},sp=1},{q="Why did Yala stay behind?",a="Yala Windwatcher chose to remain at the site of conflict to finish dealing with any lingering stragglers while sending you ahead with the urgent intelligence.",al={"why yala stays","where did yala go","yala windwatcher role"}}},ang={["class:Shaman"]="The revelation that the Al'Aketh are deliberately agitating wind spirits strikes at the core of a Shaman's duty to maintain elemental balance.",["class:Druid"]="The defense of Thendal Grove and the preservation of peaceful harmony within Zephras Isle's sacred grounds naturally aligns with Druidic vows."},kw={"al'aketh","cult","rorian","standing stones","thendal grove","wind spirits","yala windwatcher","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92465","zone:zephras","subzone:vice"},m={start="Yala Windwatcher",["end"]="Rorian the Dayseeker",level="4",id=92469},src={"Return to Rorian"},fv=true}
E["quest:92470"] = {t="quest",n="Foul Matriarch",z="zephras",s="Foul Matriarch is a trial of survival assigned by Aetheen of the Gales to budding initiates in Thendal Village. The task demands delving into the southern caves to culled the scavenging ursera and slay their vicious den mother, Urs'anah. Completing the hunt proves that an adventurer possesses the resolve required to face greater perils across Zephras Isle.",h="Foul Matriarch is a trial of survival assigned by Aetheen of the Gales to budding initiates in Thendal...",sec={{t="A Test of Resolve",b="Aetheen of the Gales maintains a watchful eye on newcomers finding their footing around Thendal Village. Once an initiate demonstrates early competence, Aetheen issues a dangerous rite of passage: a direct assault against the predatory wildlife threatening the perimeter. Rather than simply fighting on the open paths, the initiate is sent directly into the dark caves to the south to thin the local ursera packs and confront their broodmother.",sp=0},{t="The Threat of Urs'anah",b="The local rangers have long noted the ferocity of the ursera, but none poses a greater threat to the haven than Urs'anah, their formidable matriarch. Sheltered deep within Thendal Cave, she directs her scavengers and aggressively defends her lair. Bringing back her severed head serves as definitive proof that an adventurer is capable of handling ferocious beasts and is ready to push beyond the borders of the starting grove.",sp=0}},faq={{q="Who assigns the task to kill Urs'anah?",a="Aetheen of the Gales offers the trial from Thendal Village. She monitors promising newcomers who have gained the notice of local figures like Rorian before testing their mettle with this dangerous hunt.",al={"who gives foul matriarch","foul matriarch quest giver","who is aetheen of the gales"}},{q="Where can Urs'anah and the ursera scavengers be found?",a="Urs'anah and the ursera scavengers reside in the caves situated to the south and southwest of Thendal Village, up in the hills within Thendal Grove. The matriarch herself makes her den in the deep recesses of the cavern.",al={"urs'anah location","where is ursanah","ursera cave zephras","thendal cave location"}},{q="What is an ursera?",a="Ursera are aggressive, bear-like predators indigenous to the wilder crags of Zephras Isle. Left unchecked, their scavenging packs establish dens dangerously close to populated settlements like Thendal Village.",al={"what is an ursera","ursera lore","are ursera bears"}},{q="What does completing this hunt signify for an adventurer?",a="Slaying Urs'anah serves as a pivotal rite of passage. By overcoming both cultist interlopers and the grove's most dangerous wildlife, the hunter proves they are prepared to leave the sanctuary of Thendal Village and take on wider responsibilities across Zephras Isle.",al={"why kill ursanah","importance of foul matriarch"}}},ang={["race:Skyborne"]="For Skyborne initiates, proving mastery over terrestrial predators like Urs'anah demonstrates ground-level self-sufficiency and readiness to venture beyond their secluded beginnings.",["class:Hunter"]="Tracking a ferocious cave-dwelling matriarch like Urs'anah is an elemental test of beast-lore and martial resolve for emerging hunters."},kw={"aetheen of the gales","foul matriarch","thendal cave","thendal grove","thendal village","urs'anah","ursera","zephras isle"},rel={"quest:92471","quest:92473","zone:zephras"},m={start="Aetheen of the Gales",level="5",id=92470},src={"Foul Matriarch"},fv=true}
E["quest:92471"] = {t="quest",n="Aetheen of the Gales",z="zephras",s="This quest marks a rite of passage for young adventurers on Zephras Isle, directing them to report to one of the island's leading authorities. After completing early trials under Rorian the Dayseeker, promising youths are sent into Thendal Grove to meet Aetheen of the Gales, an elder who reads the winds and evaluates the next generation.",h="This quest marks a rite of passage for young adventurers on Zephras Isle, directing them to report to one of...",sec={{t="A Measure of Potential",b="The early tasks set before novitiates on Zephras Isle are not merely mundane chores; they serve as informal tests to evaluate whether rising youths possess the grit and spirit needed to defend their homeland. Recognizing that island life faces growing trials, mentors such as Rorian the Dayseeker keep a watchful eye on candidates who prove capable of handling greater responsibility.",sp=0},{t="The Wind-Reader of Thendal Grove",b="Deep within Thendal Grove sits Aetheen of the Gales, a respected member of the Council of Elders governing Zephras Isle. Aetheen spends her time reading the currents of the air and assessing young shen'dorei as they come of age. Stepping before her signifies that an initiate has outgrown minor perimeter duties and is ready to tackle direct threats facing the community.",sp=0}},faq={{q="Who is Aetheen of the Gales?",a="Aetheen of the Gales is a leader on Zephras Isle and a seated member of the Council of Elders. She monitors the winds in Thendal Grove and personally assesses young shen'dorei who come of age to ensure they are prepared to defend their home.",al={"who is aetheen","aetheen of the gales role","aetheen zephras"}},{q="Why does Rorian send players to meet Aetheen?",a="Rorian the Dayseeker evaluates novice adventurers through their early duties. Once an adventurer proves their capability and resilience, Rorian directs them to Aetheen so their skills can be judged and directed toward higher-level challenges facing the island.",al={"why meet aetheen","rorian sends to aetheen","purpose of this quest"}},{q="Where can Aetheen of the Gales be found?",a="She can be found residing within Thendal Grove on Zephras Isle, where she studies the flow of the winds and oversees coming-of-age trials for local youths.",al={"aetheen location","where is aetheen","thendal grove aetheen"}},{q="What is the Council of Elders?",a="The Council of Elders is the governing body guiding the shen'dorei on Zephras Isle. Leaders like Aetheen sit on this council to oversee the survival, leadership, and readiness of their community.",al={"council of elders zephras","who rules zephras"}},{q="What happens after reporting to Aetheen?",a="Upon confirming a young adventurer's willingness to serve Zephras Isle, Aetheen assigns serious tasks to address local wilderness dangers, beginning with threats like aggressive wildlife and foul matriarchs.",al={"next quest after aetheen","what does aetheen want"}},{q="What does 'coming of age' mean for shen'dorei on Zephras Isle?",a="For youths on Zephras Isle, coming of age involves proving oneself through physical and magical trials. Rather than a mere ceremony, it demands that young shen'dorei demonstrate practical capability to an island elder like Aetheen before stepping into service.",al={"shen'dorei coming of age","zephras coming of age"}}},kw={"aetheen of the gales","council of elders","rorian the dayseeker","shen'dorei","thendal grove","zephras isle"},rel={"quest:92469","npc:rorian-the-dayseeker","zone:zephras","quest:92460"},m={start="Rorian the Dayseeker",["end"]="Aetheen of the Gales",level="4",id=92471},src={"Aetheen of the Gales (quest)"},fv=true}
E["quest:92472"] = {t="quest",n="The Next Step",z="zephras",s="Following the resolution of the immediate beast threats near Thendal Village, Elder Aetheen of the Gales directs travelers southward toward Shen'dar Village. The journey marks a shift from clearing wild fauna to confronting the organized zealotry of the Al'Aketh Cult, who revere the Windlord Al'Akir.",h="Following the resolution of the immediate beast threats near Thendal Village, Elder Aetheen of the Gales...",sec={{t="Leaving Thendal Village",b="After proving capable against the local predators and the matriarchs plaguing the northern wilderness of Zephras Isle, adventurers are called to broader duties. Elder Aetheen of the Gales recognizes that simple pest control is secondary to the true peril taking root across the island. To protect the isle's inhabitants, capable defenders must be dispatched to support the outlying settlements.",sp=0},{t="The Looming Shadow of the Cult",b="The primary danger facing southern Zephras is the Al'Aketh Cult. Described as ruthless zealots, the cultists dedicate themselves to Al'Akir the Windlord, ruler of the elemental realm of Skywall. Their growing power poses an immediate menace to Shen'dar Village. In response, Aetheen sends travelers southward down the road, past lurking ambushers in the highlands, to reinforce Constable Aonda's local guard.",sp=0}},faq={{q="Where does this journey lead?",a="The road leads south from Thendal Village into the Shen'dar Highlands and ends at Shen'dar Village, where Constable Aonda manages the local defense.",al={"where do i go","next hub","destination"}},{q="Who is Constable Aonda?",a="Constable Aonda is the civic and military authority maintaining order in Shen'dar Village, currently tasked with protecting the town against escalating cultist threats.",al={"constable aonda","who is aonda"}},{q="What is the Al'Aketh Cult?",a="The Al'Aketh are brutal zealots on Zephras Isle who worship Al'Akir the Windlord, the elemental lord of Skywall. Their aggressive growth poses a direct threat to the island's settlements.",al={"who are the al'aketh","al'aketh cult lore","cultists"}},{q="Who is Al'Akir?",a="Al'Akir the Windlord is the elemental ruler of the skies and master of Skywall, revered by air elementals and worshiped fanatically by the Al'Aketh Cult.",al={"who is alakir","windlord","skywall ruler"}},{q="Why does Elder Aetheen send travelers away from Thendal?",a="With immediate threats around Thendal handled, Aetheen directs proven defenders to Shen'dar Village, where the Al'Aketh Cult's aggressive advances present a much larger danger to the island as a whole.",al={"why leave thendal","aetheen's goal"}},{q="What hazards are along the road to Shen'dar Village?",a="The trail south passes through the Shen'dar Highlands, where Al'Aketh Ambushers and rogue cult thugs harass travelers traveling between the island's settlements.",al={"road hazards","traveling south","highland danger"}}},ang={["race:Skyborne"]="For the Skyborne, confronting the Al'Aketh represents a direct fight against elemental fanaticism threatening the safety of their home settlements across Zephras Isle.",["class:Shaman"]="Shaman will recognize the danger of mortals blindly worshiping elemental lords like Al'Akir, whose volatile nature often demands servitude rather than balance."},kw={"aetheen of the gales","al'aketh cult","al'akir","constable aonda","shen'dar village","skywall","thendal village","zephras isle"},rel={"quest:92471","quest:92470","zone:zephras","quest:92544","quest:96627","topic:skywall"},m={start="Aetheen of the Gales",["end"]="Constable Aonda",level="5",id=92472},src={"The Next Step (Skyborne)"},fv=true}
E["quest:92473"] = {t="quest",n="Aggressive Encroachment",z="zephras",s="Aggressive Encroachment is a task issued by Valreaa Valewind to protect the local settlement from desperate wildlife. Ursera from a nearby den have grown increasingly bold, wandering into the village and threatening its inhabitants.",h="Aggressive Encroachment is a task issued by Valreaa Valewind to protect the local settlement from desperate...",sec={{t="Desperate Predators",b="The ursera population nesting southwest of the village has become an urgent safety hazard. Recently, a hungry adolescent beast strayed right up to the base of the village's central elder tree, nearly mauling a young child playing nearby. The settlement's rangers were forced to cut the creature down before tragedy struck.",sp=0},{t="Culling the Grove",b="Recognizing that hunger and starvation are driving these predators to attack civilized grounds, the rangers have ordered a cull of the scrawniest ursera in Thendal Grove. By eliminating the desperate and malnourished beasts prowling outside the dens, the Rangers of the Grove hope to halt further encroachment until they can uncover what is disturbing the local wildlife.",sp=0}},faq={{q="Who offers Aggressive Encroachment?",a="The quest is given by Valreaa Valewind, a leader among the rangers who keeps watch over the grove and protects the nearby settlement from predatory beasts.",al={"who gives aggressive encroachment","quest giver","valreaa valewind quest"}},{q="Why are the ursera wandering so close to the village?",a="The ursera are suffering from starvation and desperation, driving them to venture far beyond their normal hunting grounds into the heart of the settlement.",al={"why ursera attack","ursera aggression","why are ursera mad"}},{q="Where can the scrawny ursera be found?",a="The scrawny ursera prowl Thendal Grove southwest of the village, lingering outside around the entrances of their den rather than deep within the cave.",al={"where are scrawny ursera","ursera location","thendal grove bears"}},{q="What near-tragedy prompted this cull?",a="An adolescent ursera wandered directly to the elder tree in the middle of the village and tried to attack a young boy playing nearby. Rangers killed the beast just in time to save his life.",al={"ursera attack boy","what happened in the village","boy near elder tree"}},{q="Why are the ursera behaving so erratically?",a="The rangers have noted that the ursera have grown unusually aggressive recently, but the underlying cause behind their sudden food shortage and behavioral shift remains an open question.",al={"what changed with ursera","why ursera starving"}},{q="What proof does Valreaa Valewind require?",a="Valreaa requests six Scrawny Ursera Claws taken from the malnourished beasts prowling the grove to ensure the dangerous predators have been dealt with.",al={"what do I collect","aggressive encroachment objective"}}},ang={["class:Hunter"]="Hunters will immediately understand the danger posed by starving predators, as desperate beasts abandon their natural wariness of humanoid settlements when driven by famine.",["class:Druid"]="Druids will recognize the delicate balance of the grove being disrupted, noting that the sudden aggression and malnutrition of the local ursera points to an unseen disturbance in the local ecosystem."},kw={"claws","elder tree","encroachment","scrawny ursera","thendal grove","ursera","valreaa valewind"},rel={"zone:zephras"},m={start="Valreaa Valewind",level="4",id=92473},src={"Aggressive Encroachment"},fv=true}
E["quest:92474"] = {t="quest",n="Falling With Style",z="zephras",s="\"Falling With Style\" is an introductory rite of passage for young Skyborne in Thendal Village. Offered atop the local watchtower by the mischievous Myriaal Mistwake, it challenges novices to test their innate slow-fall ability by leaping from the platform toward Rorian the Dayseeker below.",h="\"Falling With Style\" is an introductory rite of passage for young Skyborne in Thendal Village.",sec={{t="A Leap from the Tower",b="Perched high above Thendal Village on Zephras Isle, Myriaal Mistwake invites young Skyborne to test their heritage through a game of daring. Rather than treating their innate magical gifts as sacred relics kept under strict restraint, Myriaal encourages newcomers to leap into the open air from the watchtower ledge. The purpose is practical as well as playful: mastering the instinctive art of walking upon air before life beyond the grove demands it in perilous situations.",sp=0},{t="A Difference in Temperament",b="The exercise serves as a vivid demonstration of two contrasting Skyborne attitudes. While Myriaal delights in sudden descents and startles onlookers for amusement, Rorian the Dayseeker embodies traditional caution. When novices glide down to land squarely before him, Rorian admonishes the reckless display, warning that thoughtlessly exhausting one's magical gifts can leave a traveler helpless when danger strikes. Even so, he concedes that controlled practice within the safety of the village has its place.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest teaches novice Skyborne how to handle their innate Walk on Air ability, familiarizing them with controlling slow descents from elevated heights.",al={"what does this quest do","falling with style purpose","why do this quest"}},{q="Who gives the quest and where?",a="It is given by Myriaal Mistwake, who waits atop the wooden watchtower overlooking Thendal Village on Zephras Isle.",al={"quest giver","where to start falling with style","who gives falling with style"}},{q="Who do you land in front of?",a="You land near Rorian the Dayseeker, a village elder or guardian who is annoyed by Myriaal's antics but accepts the turn-in.",al={"who to land near","who is rorian","falling with style turn in"}},{q="Why is Rorian upset by the jump?",a="Rorian believes innate magical gifts should be conserved and treated with discipline, rather than wasted on practical jokes that startle people.",al={"why is rorian mad","rorian reaction","why does rorian scold you"}},{q="What ability is being practiced?",a="It teaches the use of Walk on Air, an innate Skyborne ability that slows a character's descent and prevents falling damage.",al={"what ability is used","walk on air quest","skyborne racial ability"}},{q="Where does this take place?",a="The exercise takes place in Thendal Village, located on Zephras Isle, the ancestral starting grounds of the Skyborne.",al={"quest location","where is thendal village","what zone is this"}}},ang={["race:Skyborne"]="This early trial introduces Skyborne novices to the practical mechanics and cultural debates surrounding their innate wind-walking magic."},kw={"falling with style","myriaal mistwake","rorian the dayseeker","slow fall","thendal village","walk on air","watchtower","zephras isle"},rel={"npc:rorian-the-dayseeker","topic:skyborne","zone:zephras"},m={start="Myriaal Mistwake",["end"]="Rorian the Dayseeker",level="2",id=92474},src={"Falling With Style (Skyborne)"},fv=true}
E["quest:92481"] = {t="quest",n="A Student of the Arcane",z="zephras",s="A Student of the Arcane is an introductory trial and summons for novice spellcasters on Zephras Isle. Initiated by Rorian the Dayseeker after newcomers prove their basic mettle, it directs budding mages to review a Glowing Recall Crystal and report to the local mentor, Dorii Brightwhisper.",h="A Student of the Arcane is an introductory trial and summons for novice spellcasters on Zephras Isle.",sec={{t="A Message in Crystal",b="After helping manage the troublesome vuldren lurking near Thendal Grove, fledgling mages are entrusted with a curious artifact: a Glowing Recall Crystal. Left behind by Dorii Brightwhisper, the island's resident arcane instructor, the crystal serves as a magically recorded missive designed to test an initiate's aptitude and welcome them into deeper mystical study.",sp=0},{t="Rediscovering the Arcane",b="According to Dorii Brightwhisper, mastery of the arcane has slowly dwindled among their people during their long millennia spent secluded high in the clouds. Dorii views each new practitioner not merely as a student, but as an essential pioneer meant to recover lost knowledge and restore their people's once-mighty magical heritage.",sp=0}},faq={{q="What is the Glowing Recall Crystal?",a="The Glowing Recall Crystal is a small magical focus entrusted to Rorian the Dayseeker by Dorii Brightwhisper. It holds an inscribed message intended to introduce young apprentices to the fundamentals of arcane communication.",al={"recall crystal","crystal message","what does the crystal do"}},{q="Who is Dorii Brightwhisper?",a="Dorii Brightwhisper is the resident mage trainer situated in the structure behind Rorian the Dayseeker in Thendal Grove on Zephras Isle. Dorii guides young mages who seek to reclaim their people's ancient arcane traditions.",al={"who is dorii","mage trainer zephras","dorii location"}},{q="Why has arcane magic waned among the people of Zephras?",a="As Dorii explains, the arcane arts gradually fell into decline over the thousands of years their people lived secluded up in the clouds. Consequently, instructors like Dorii are eager to train new novices to search for and recover what was lost.",al={"why did magic fade","skyborne arcane lore","lost arcane magic"}},{q="Who gives this quest?",a="Rorian the Dayseeker offers this quest in Thendal Grove on Zephras Isle once an aspiring mage has completed the preliminary task 'Harmony in Balance'.",al={"quest giver","who starts a student of the arcane","rorian quest"}},{q="Where can I find Dorii Brightwhisper?",a="Dorii Brightwhisper resides in the structure directly behind Rorian the Dayseeker within Thendal Grove.",al={"dorii brightwhisper location","where is the mage trainer","find dorii"}},{q="What prerequisite must be completed before starting this quest?",a="You must first complete 'Harmony in Balance', which involves handling the local vuldren problem for Rorian the Dayseeker.",al={"prereq","prerequisites","what quest comes before"}}},ang={["class:Mage"]="This task marks the formal commencement of a mage's formal tutelage under Dorii Brightwhisper, framing your magical journey as an effort to restore long-lost cloudborne arcane secrets.",["race:Skyborne"]="Dorii highlights that millennia of isolation among the clouds caused arcane traditions to wane, making young apprentices central to revitalizing their cultural heritage."},kw={"dorii brightwhisper","glowing recall crystal","mage quest","rorian the dayseeker","student of the arcane","thendal grove","vuldren","zephras isle"},rel={"quest:92461","npc:rorian-the-dayseeker","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Dorii Brightwhisper",level="2",faction="Alliance",id=92481},src={"A Student of the Arcane"},fv=true}
E["quest:92482"] = {t="quest",n="The Way of the Hunter",z="zephras",s="The Way of the Hunter is an introductory training quest for fledgling hunters in Thendal Grove on Zephras Isle. After proving their mettle against the local vuldren threat, young trackers are directed by Rorian the Dayseeker to present themselves to Tai'ree Farsight to begin their formal tutelage.",h="The Way of the Hunter is an introductory training quest for fledgling hunters in Thendal Grove on Zephras...",sec={{t="A Summons to the Hunt",b="Upon returning from thinning the disruptive vuldren prowling the outskirts of Thendal Grove, young hunters find that their practical skills have caught local attention. Rorian the Dayseeker passes along a scribbled summons from Tai'ree Farsight, the grove's resident hunter trainer. For novice rangers setting out into the wider wilds of Zephras Isle, this marked the shift from simple island defense to true martial and survival instruction.",sp=0},{t="The Tutelage of Tai'ree",b="Found near the center of the village, Tai'ree Farsight welcomes promising pupils with stern realism. Emphasizing that thriving in untamed nature demands sharp senses and lightning reflexes, she offers guidance born of her own long years of experience. Her mentorship marks the foundational steps for any island tracker looking to hone their marksmanship and survival skills.",sp=0}},faq={{q="Who offers this task?",a="Rorian the Dayseeker offers this task in Thendal Grove on Zephras Isle after you assist him with the local vuldren infestation in the quest 'Harmony in Balance'.",al={"who gives the way of the hunter","quest starter","rorian quest"}},{q="Who is Tai'ree Farsight?",a="Tai'ree Farsight is the resident hunter trainer in Thendal Grove, stationed near the center of the village. She oversees the training and discipline of aspiring marksmen and island trackers.",al={"where is tai'ree","hunter trainer thendal grove","tai'ree farsight location"}},{q="What is the purpose of the Scribbled Note?",a="The Scribbled Note is a message left by Tai'ree Farsight while you were away dealing with the vuldren. It directs you to seek her out directly in the village square to begin advanced training.",al={"scribbled note","what does the note say","hunter note"}},{q="Where does this quest take place?",a="This quest takes place entirely within Thendal Grove, an outpost settlement situated on Zephras Isle.",al={"quest zone","hunter quest location","where is thendal grove"}},{q="What prerequisite must be completed before this quest?",a="You must first complete 'Harmony in Balance' for Rorian the Dayseeker, proving your initial competence by dealing with the aggressive vuldren near the grove.",al={"prereq for the way of the hunter","how to unlock","previous quest"}},{q="What does Tai'ree Farsight teach new hunters?",a="Tai'ree Farsight acts as your class trainer. Speaking with her introduces the core philosophy of island tracking and opens access to foundational hunter abilities and combat techniques.",al={"what does tai'ree do","why talk to tai'ree"}}},ang={["class:Hunter"]="This quest serves as the essential rite of passage for fledgling hunters on Zephras Isle, formalizing their training under Tai'ree Farsight."},kw={"hunter trainer","rorian the dayseeker","scribbled note","tai'ree farsight","the way of the hunter","thendal grove","vuldren","zephras"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Tai'ree Farsight",level="2",id=92482},src={"The Way of the Hunter"},fv=true}
E["quest:92483"] = {t="quest",n="At Home in the Shadows",z="zephras",s="\"At Home in the Shadows\" is an introductory rogue quest on Zephras Isle. After aiding Rorian the Dayseeker in Thendal Grove, budding rogues are directed to read a summons and meet their local class mentor, Akeri Duskblade. The quest marks the moment young rogues transition from general village chores to serious stealth and combat training.",h="\"At Home in the Shadows\" is an introductory rogue quest on Zephras Isle.",sec={{t="A Shady Invitation",b="While handling basic threats around Thendal Grove, young rogues draw the attention of Akeri Duskblade, the grove's resident rogue trainer. Rather than mingling openly in the settlement, Akeri passes a simple note through Rorian the Dayseeker. Rorian recognizes that despite Akeri's suspicious demeanor, the mentor understands the practical skills needed to survive outside the grove's sheltered boundaries.",sp=0},{t="Lessons in the Watchtower",b="Tucked away inside the village watchtower, Akeri Duskblade wastes no time mincing words. He evaluates every newcomer's footing and awareness immediately upon their arrival, warning that sloppy footwork outside Thendal Grove leads straight to an early grave. By surviving Akeri's scrutiny, a rogue takes their first formal step into mastering stealth, precision, and survival on Zephras Isle.",sp=0}},faq={{q="Who gives the quest At Home in the Shadows?",a="Rorian the Dayseeker offers the quest in Thendal Grove on Zephras Isle after you complete \"Harmony in Balance.\"",al={"who starts at home in the shadows","quest giver at home in the shadows","rorian quest"}},{q="Where can I find Akeri Duskblade?",a="Akeri Duskblade is located inside the village watchtower in Thendal Grove on Zephras Isle.",al={"akeri duskblade location","where is akeri duskblade","find akeri"}},{q="What is the Simple Note given during the quest?",a="The Simple Note is a message left by Akeri Duskblade requesting an audience with promising rogues. You must read it before speaking to Akeri to complete your objective.",al={"simple note zephras","what is the note","read simple note"}},{q="Is this quest available to all classes?",a="No, this quest is specifically intended for rogues learning their trade in Thendal Grove.",al={"can non rogues do this quest","is at home in the shadows rogue only","class requirement"}},{q="What does Akeri Duskblade teach?",a="Akeri Duskblade serves as the local rogue trainer in Thendal Grove, providing instruction in stealth, cunning, and bladecraft for novices beginning their journey across Zephras Isle.",al={"akeri duskblade role","who is akeri","rogue trainer thendal grove"}},{q="What prerequisite quest must be completed first?",a="You must first complete \"Harmony in Balance\" for Rorian the Dayseeker before he hands you Akeri's note.",al={"at home in the shadows prerequisite","previous quest","unlock at home in the shadows"}}},ang={["class:Rogue"]="This quest establishes your formal rogue training on Zephras Isle, introducing you to Akeri Duskblade in the Thendal Grove watchtower."},kw={"akeri duskblade","at home in the shadows","rogue quest","rogue trainer","rorian the dayseeker","simple note","thendal grove","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Akeri Duskblade",level="2",id=92483},src={"At Home in the Shadows"},fv=true}
E["quest:92484"] = {t="quest",n="Embracing the Elements",z="zephras",s="Embracing the Elements is an introductory shaman quest in Thendal Grove on Zephras Isle. Initiated by Rorian the Dayseeker, the task directs young practitioners to Windshaper Boro, the local shaman trainer. It introduces the silent rift between the local people and the elemental spirits of the winds.",h="Embracing the Elements is an introductory shaman quest in Thendal Grove on Zephras Isle.",sec={{t="A Summons to the Elements",b="After helping manage the vuldren pest problem around the village, aspiring shamans are approached by Rorian the Dayseeker. During their time afield, Windshaper Boro left behind a humming recall crystal, signaling that it is time for formal elemental instruction to begin in the center of the grove.",sp=0},{t="The Silent Winds",b="Upon meeting Windshaper Boro, he explains the difficult state of local shamanism. The spirits of the four winds abruptly severed communication years ago, abandoning their former communion. Zephras shamans now dedicate themselves to deep study of the natural world, striving through rigorous training to bridge the silence and coax the spirits into dialogue once more.",sp=0}},faq={{q="Who gives the quest Embracing the Elements?",a="The quest is provided by Rorian the Dayseeker in Thendal Grove on Zephras Isle, immediately after you help handle the local vuldren problem.",al={"embracing the elements quest giver","who starts embracing the elements"}},{q="Where is Windshaper Boro located?",a="Windshaper Boro is located near the center of Thendal Grove on Zephras Isle, serving as the settlement's resident shaman trainer.",al={"windshaper boro location","where is boro","find windshaper boro"}},{q="Why did the elemental spirits stop speaking to the people here?",a="According to Windshaper Boro, the elemental spirits abruptly ceased all dialogue and left the people years ago. The local shamans do not fully understand why the break occurred, but they continue their studies in hopes of renewing that lost connection.",al={"why are the winds silent","spirits of the four winds silent","what happened to the wind spirits"}},{q="What is the Humming Recall Crystal?",a="The Humming Recall Crystal is an item left behind by Windshaper Boro while you were away helping the settlement. Examining it marks your readiness to take up elemental training under Boro's guidance.",al={"humming recall crystal","recall crystal zephras"}},{q="What prerequisite quest leads to Embracing the Elements?",a="It follows the quest Harmony in Balance, where you deal with the vuldren disrupting the surrounding area.",al={"embracing the elements prequest","what comes before embracing the elements"}},{q="What role does Windshaper Boro play in Thendal Grove?",a="Windshaper Boro serves as the community's shaman trainer, guiding new initiates in elemental communion and the study of the natural world.",al={"what does boro do","windshaper boro role"}}},ang={["class:Shaman"]="This quest represents an initiate's first formal introduction to Windshaper Boro, outlining the tragic silence of the elemental winds and the lifelong quest to restore communion.",["faction:Horde"]="For Horde travelers visiting Zephras Isle, the quest introduces the unique struggles of the island's elemental callers compared to the traditional earth and spirit traditions of the mainland."},kw={"embracing the elements","humming recall crystal","rorian the dayseeker","shaman","spirits of the four winds","thendal grove","windshaper boro","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Windshaper Boro",level="2",faction="Horde",id=92484},src={"Embracing the Elements"},fv=true}
E["quest:92485"] = {t="quest",n="A Student of Nature",z="zephras",s="A Student of Nature marks a fledgling druid's introduction to formal training on Zephras Isle. After helping restore local harmony, novice druids are summoned by Xyton Silverwind beneath the boughs of Thendal Grove. It serves as the opening gateway into understanding the deeper balance between flora and fauna on the isle.",h="A Student of Nature marks a fledgling druid's introduction to formal training on Zephras Isle.",sec={{t="A Summons from the Grove",b="Following the resolution of local disturbances caused by overzealous wildlife, Rorian the Dayseeker delivers a personal summons to young initiates. Left behind by the local mentor Xyton Silverwind, the folded parchment invites aspiring druids to step forward and dedicate themselves to the deeper mysteries of the wild. It signals that an initiate's natural talents have caught the eye of the grove's elders.",sp=0},{t="Keepers of the Tapestry",b="Meeting Xyton Silverwind on the lower level of the great tree in Thendal Grove anchors a novice to their calling. Silverwind regards the vibrant flora and fauna of Zephras Isle as an intricate living tapestry, one that demands constant preservation and vigilant balance. To walk the path of the fang, claw, feather, and branch requires enduring mentorship, and this meeting marks the true beginning of that lifelong stewardship.",sp=0}},faq={{q="Who sends the player to Xyton Silverwind?",a="Rorian the Dayseeker hands over the folded parchment that directs you to Xyton Silverwind after you help address the vuldren issues around the grove.",al={"who gives a student of nature","quest giver","rorian"}},{q="Where is Xyton Silverwind located?",a="Xyton Silverwind resides on the ground floor of the great tree in Thendal Grove, situated just behind Rorian the Dayseeker on Zephras Isle.",al={"xyton silverwind location","where is xyton","druid trainer location"}},{q="What is the purpose of this quest?",a="This quest introduces novice druids to their class trainer, Xyton Silverwind, who serves as their primary teacher and guide in maintaining the natural balance of Zephras Isle.",al={"why do this quest","quest goal","druid training start"}},{q="What does Xyton Silverwind teach novice druids about Zephras Isle?",a="Silverwind teaches that the island's plant and animal life form a delicate, interconnected tapestry that requires active care and balance through the discipline of fang, claw, feather, and branch.",al={"what does xyton say","zephras nature balance","druid role zephras"}},{q="What prerequisite must be completed before receiving this summons?",a="Initiates must first complete Harmony in Balance for Rorian the Dayseeker, dealing with the unruly vuldren population before receiving Silverwind's note.",al={"prereq quest","prior quest","before student of nature"}},{q="What is contained within the Folded Parchment?",a="The folded parchment is a direct note left by Xyton Silverwind instructing the promising young druid to seek him out for further training beneath the canopy of the great tree.",al={"folded parchment note","silverwind note","what is on parchment"}}},ang={["class:Druid"]="This rite of passage connects you directly to Xyton Silverwind, initiating your lifelong training in the arts of the wild, the fang, and the branch."},kw={"druid","folded parchment","rorian the dayseeker","thendal grove","vuldren","xyton silverwind","zephras isle"},rel={"quest:92461","npc:rorian-the-dayseeker","zone:zephras","topic:druid"},m={start="Rorian the Dayseeker",["end"]="Xyton Silverwind",level="2",id=92485},src={"A Student of Nature"},fv=true}
E["quest:92532"] = {t="quest",n="The Warrior's Path",z="zephras",s="The Warrior's Path is an introductory martial quest offered to budding fighters on Zephras Isle. Following instructions delivered through Rorian the Dayseeker, young warriors are directed to Blademaster Ren in the Thendal Village watchtower. Ren stands ready to offer combat instruction and discipline to those prepared to shield their people.",h="The Warrior's Path is an introductory martial quest offered to budding fighters on Zephras Isle.",sec={{t="A Summons to the Watchtower",b="Upon returning to Rorian the Dayseeker in Thendal Village after restoring balance nearby, aspiring fighters receive word that the settlement's blademaster has taken notice of them. Rorian delivers a crumpled note penned by Ren herself, asking the novice to seek her out directly. Elevated above the settlement within the village watchtower, Ren keeps an observant eye over both the island's borders and the recruits who may one day defend them.",sp=0},{t="The Mantle of Protection",b="Reaching the watchtower introduces the warrior to Blademaster Ren's philosophy of combat. To Ren, martial mastery is not simply an exercise in brute strength, but a vital duty to lead, endure, and protect in an increasingly uncertain world. She pledges her guidance to the recruit as they hone their skills, offering rigorous training as they grow strong enough to face the greater perils threatening their home.",sp=0}},faq={{q="Who sends me to find Blademaster Ren?",a="Rorian the Dayseeker directs you to Blademaster Ren after you complete tasks in Thendal Village. While you were away, Ren specifically requested that Rorian send you to her watchtower upon your return.",al={"who starts this","quest giver","rorian role"}},{q="Where can I find Blademaster Ren?",a="Blademaster Ren is located inside the watchtower in Thendal Village on Zephras Isle, where she oversees the village and trains novice combatants.",al={"where is blademaster ren","ren location","thendal watchtower"}},{q="What is the Crumpled Note?",a="The Crumpled Note is a personal summons delivered to you by Rorian on behalf of Blademaster Ren, instructing you to read it and report to the Thendal Village watchtower for formal martial training.",al={"crumpled note","what does note say","ren note"}},{q="What does Blademaster Ren teach young warriors?",a="Blademaster Ren emphasizes vigilance, leadership, and protection. She reminds trainees that as the world shifts and perils mount, warriors must possess the will to stand between danger and their people.",al={"ren teaching","what does ren train","warrior purpose"}},{q="Is this quest required for warrior training on Zephras Isle?",a="It serves as the formal introduction to your class trainer in Thendal Village, pointing you directly to Blademaster Ren so you know where to return for future martial techniques.",al={"do i have to do this","warrior trainer intro","is it mandatory"}},{q="What does Ren mean by 'may the winds guide you'?",a="This traditional blessing reflects the island culture of Zephras Isle, wishing travelers safe passage, focus, and fortune as they step out into unfamiliar and perilous territories.",al={"may the winds guide you meaning","wind quote","ren farewell"}}},ang={["class:Warrior"]="This quest represents the formal beginning of your martial education in Thendal Village, introducing you to Blademaster Ren as your mentor."},kw={"blademaster ren","crumpled note","rorian the dayseeker","thendal village","warrior's path","watchtower","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Blademaster Ren",level="2",id=92532},src={"The Warrior's Path"},fv=true}
E["quest:92544"] = {t="quest",n="Al'Aketh Thugs",z="zephras",s="The peaceful roads around Thendal Grove are threatened by a violent band of Al'Aketh cultists occupying the nearby temple ruins. Dispatched from the Shrine of Akir under orders to harass wayfarers and force recruits into their ranks, these zealots pose an immediate danger to local travelers. Hanaa Nightwind tasks adventurers with breaking their hold and slaying their brutish commander.",h="The peaceful roads around Thendal Grove are threatened by a violent band of Al'Aketh cultists occupying the...",sec={{t="Cultist Ruffians in the Ruins",b="Just southwest of Thendal Grove lie ancient temple ruins that should offer quiet shelter to wanderers. Instead, the grounds have been overtaken by the Al'Aketh, an aggressive cult driven by fanatical ambition. Far from peaceful worshipers, these cultists act as highwaymen and enforcers, preying upon those traveling along the outskirts of the grove. The Rangers stationed nearby suspect these ruffians were sent directly by High Priestess Lorthuna from the Shrine of Akir to bully and coerce the populace into bowing to the cult's influence.",sp=0},{t="Malduko Cloudcrush",b="Heading the rabble at the temple ruins is Malduko Cloudcrush, a brutal leader who uses violence and fear to keep both his initiates and unsuspecting wayfarers in line. With brutes and newly indoctrinated neophytes answering his commands, Malduko has established an aggressive outpost right on the doorstep of Thendal Grove. By striking down Cloudcrush and scattering his underlings, Hanaa Nightwind hopes to shatter the cult's confidence and send a clear warning that zealotry and coercion will not be tolerated in these lands.",sp=0}},faq={{q="Who are the Al'Aketh?",a="The Al'Aketh are a fanatical cult operating on Zephras. Led by figures like High Priestess Lorthuna at the Shrine of Akir, they use strong-arm tactics, intimidation, and violence to force local travelers and residents into joining their ranks.",al={"what is the al'aketh","al'aketh cult","who are alaketh"}},{q="Why are the cultists attacking Thendal Grove?",a="They have established a camp in the temple ruins southwest of Thendal Grove to ambush travelers leaving the area. By terrorizing wayfarers on the road, they hope to pressure and coerce the local people into submitting to the cult.",al={"why are cultists here","why thendal grove","cultist motive"}},{q="Who is Malduko Cloudcrush?",a="Malduko Cloudcrush is a violent brute leading the Al'Aketh encampment at the temple ruins. Described as a monster by Hanaa Nightwind, he directs the brutes and neophytes who prey on nearby roads.",al={"malduko","cloudcrush","who is malduko cloudcrush"}},{q="Who is Hanaa Nightwind?",a="Hanaa Nightwind is one of the Rangers guarding Thendal Grove. She stays stationed at her post along the road to warn travelers of the nearby cultist ambush, relying on capable adventurers to clear out the threat.",al={"hanaa","hanaa nightwind","quest giver"}},{q="Who sent these cultists to the ruins?",a="Hanaa suspects they were dispatched by High Priestess Lorthuna, who oversees cult activities from the Shrine of Akir.",al={"who commands them","cult leader","who sent malduko"}},{q="What else can be found near the temple ruins?",a="Aside from the Al'Aketh encampment, an active Ley Line is located within the ancient ruins at the southwest end of the area.",al={"ruins ley line","temple ruins secret","ruins southwest"}}},kw={"al'aketh brute","al'aketh neophyte","al'aketh thugs","hanaa nightwind","high priestess lorthuna","malduko cloudcrush","shrine of akir","thendal grove"},rel={"quest:92471","zone:zephras"},m={start="Hanaa Nightwind",level="5",id=92544},src={"Al'Aketh Thugs"},fv=true}
E["quest:92597"] = {t="quest",n="Reading the Ley Lines",z="zephras",s="Reading the Ley Lines is a rite of passage for young Skyborne discovering their Highborne magical heritage. Entrusted by Falorne Fallwind on Zephras Isle, novitiates travel to the standing stones in Thendal Grove to sense and draw upon the raw arcane currents surging through the elemental terrain.",h="Reading the Ley Lines is a rite of passage for young Skyborne discovering their Highborne magical heritage.",sec={{t="Arcane Currents of the Elemental Plane",b="Even within the windswept confines of the elemental plane, latent arcane conduits run beneath the earth. While strange elementals and the hostile Al'Aketh drift across Zephras Isle, subterranean ley lines have begun pushing toward the surface. To practitioners of magic, these ruptures provide direct access to untamed arcane reservoirs, offering strength to any who possess the bloodline and knowledge necessary to channel them.",sp=0},{t="Highborne Legacy",b="Falorne Fallwind urges initiates to embrace their Highborne ancestry rather than supplicate themselves to wind spirits like the local Windshapers or the zealots of the Al'Aketh. In Fallwind's view, survival against the harsh powers of the elemental plane depends not on begging foreign creatures for mercy, but on mastering the intrinsic arcane power running beneath their boots.",sp=0},{t="Thendral Standing Stones",b="Northeast of the settlement lies Thendal Grove, where ancient standing stones mark a potent ley line convergence. Surrounded by roiling winds and Al'Aketh converts, this exposed point of magical flux allows initiates to attune their senses, harmonizing with the pulse of the ley line and unleashing the full potential of their natural racial abilities.",sp=0}},faq={{q="Who gives the quest Reading the Ley Lines?",a="The quest is offered by Falorne Fallwind on Zephras Isle to young Skyborne learning to harness their ancestral arcane abilities.",al={"quest giver","falorne fallwind","who starts reading the ley lines"}},{q="Where is the ley line located?",a="The ley line is found to the northeast at the Thendal Standing Stones, situated within Thendal Grove amidst hostile elementals and Al'Aketh converts.",al={"ley line location","where is thendal grove","thendal standing stones location"}},{q="Why are ley lines present in the elemental plane?",a="Latent arcane conduits course through the ground even here in the elemental plane. Recently, these ley lines have begun breaching the surface, offering Skyborne direct access to potent currents of power.",al={"arcane in elemental plane","ley lines elemental plane lore"}},{q="How does Falorne Fallwind view the Windshapers?",a="Falorne disdains the Windshapers, viewing their veneration of air spirits as weak supplication to uncaring elemental entities, no better than the worship practiced by the Al'Aketh.",al={"falorne on windshapers","windshapers lore","windshapers vs highborne"}},{q="What ability is required to channel the ley line?",a="The quest requires using the Skyborne racial ability 'Read Ley Line' while standing within the energy convergence at the standing stones.",al={"read ley line ability","how to read ley line","racial ability used"}},{q="What benefit does tapping into ley lines provide?",a="Communing with exposed ley lines channels raw arcane energy into the user, heightening their magical prowess and providing varying effects depending on the nature of the conduit.",al={"what do ley lines do","benefits of ley lines"}}},ang={["race:Skyborne"]="This rite awakens your innate Highborne ancestry, teaching you to channel subterranean ley energy directly into your spellcasting.",["class:Mage"]="For practitioners of the arcane arts, exposed ley lines represent an invaluable reservoir of untamed power amidst an environment dominated by elemental storms."},kw={"al'aketh","falorne fallwind","highborne","ley lines","reading the ley lines","skyborne","thendal grove","thendal standing stones","windshapers","zephras isle"},rel={"zone:zephras","topic:highborne","topic:elemental-plane"},m={start="Falorne Fallwind",level="4",faction="Alliance",id=92597},src={"Reading the Ley Lines"},fv=true}
E["quest:92598"] = {t="quest",n="The Gift of Skysight",z="zephras",s="The Gift of Skysight is an early rite of passage for young Windshapers learning to harness their innate connection to the spiritual realm. Under the direction of Ventaari Brightwish, initiates travel to an Elemental Convergence to awaken their perception and listen directly to the whispers of the spirits.",h="The Gift of Skysight is an early rite of passage for young Windshapers learning to harness their innate...",sec={{t="A Sacred Perception",b="Windshapers possess an inherent bond with the elemental forces that shape their world, embodied by the sacred faculty known as Skysight. This gift allows mortal senses to attune to spiritual wavelengths, bridging the physical gap between the living and the unseen. While a Windshaper can invoke this inner vision across the wilds, doing so near points of concentrated power deepens the connection, unlocking resonant boons and hidden wisdom whispered on the wind.",sp=0},{t="The Convergence of Thendal Grove",b="Northeast of the settlement, amidst ancient standing stones, lies an Elemental Convergence in Thendal Grove. Places such as these act as focal points where raw energies gather and spirit entities linger. Ventaari Brightwish sends novices to this sacred site not simply to complete a task, but to test their spiritual constitution. Like any faculty of body or mind, Skysight requires deliberate exercise to mature, ensuring that a growing Windshaper can interpret the shifting omens of the elements upon which their people's survival depends.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest serves to instruct novice Windshapers in the practical use of their Skysight ability. Ventaari Brightwish directs initiates to an Elemental Convergence to experience how environmental power amplifies their spiritual senses.",al={"gift of skysight purpose","why do this quest","skysight training"}},{q="Who is Ventaari Brightwish?",a="Ventaari Brightwish is a spiritual guide and mentor who oversees the early training of Windshapers on Zephras Isle, teaching them to respect and hone their elemental heritage.",al={"ventaari","who is ventaari brightwish","brightwish"}},{q="What is an Elemental Convergence?",a="An Elemental Convergence is a focal point of heightened spiritual energy, often marked by ancient standing stones. These locations naturally attract elemental spirits and magnify abilities like Skysight.",al={"what is elemental convergence","elemental convergence lore","thendal grove convergence"}},{q="Where is the Elemental Convergence located?",a="The convergence is found among the standing stones located in Thendal Grove, just northeast of the settlement on Zephras Isle.",al={"where is the convergence","thendal grove location","standing stones location"}},{q="Can Skysight be used anywhere?",a="Yes. A Windshaper can call upon Skysight anywhere, but standing within an Elemental Convergence grants a far more potent boon and invites additional insights from nearby spirits.",al={"can i use skysight anywhere","skysight outside convergence","where to use skysight"}},{q="Why is Skysight considered essential for survival?",a="Skysight bridges the gap between mortals and elemental spirits. According to Ventaari, being able to perceive and heed the warnings of the elements is critical for navigating looming dangers and preserving their people.",al={"why is skysight important","skysight survival","elements survival"}}},ang={["race:Skyborne"]="For the Skyborne, Skysight is not merely an uncanny trick but a birthright bestowed by elemental patrons, grounding their cultural and spiritual identity.",["class:Shaman"]="Shamans will recognize the Elemental Convergence as sacred ground, where the boundary between mortal will and the elemental planes grows thinnest.",["faction:Horde"]="As allies on Zephras Isle, the Horde relies on the Windshapers' supernatural foresight to navigate the unmapped dangers of the island."},kw={"elemental convergence","elemental spirits","skysight","standing stones","thendal grove","ventaari brightwish","windshaper","zephras"},rel={"npc:ventaari-brightwish","zone:zephras"},m={start="Ventaari Brightwish",level="4",faction="Horde",id=92598},src={"The Gift of Skysight"},fv=true}
E["quest:93552"] = {t="quest",n="Harvesting Windstones",z="zephras",s="Harvesting Windstones is a task offered by Dalia the Collector in Thendal Grove on Zephras Isle. As the ancient elemental energies sustaining the island slowly fade, raw windstones have become an essential magical fuel source. Adventurers are sent across the grove to harvest crystalline windstone clusters before their power is lost.",h="Harvesting Windstones is a task offered by Dalia the Collector in Thendal Grove on Zephras Isle.",sec={{t="A Fading Island",b="Zephras Isle relies heavily on lingering wind magic to sustain itself, but its natural defenses are dwindling. Centuries ago, the native wind elementals who shared the island with the local elves vanished entirely. Since their departure, the ambient magic upholding the land and the great anchor pylons has been in a slow, steady decline. For the residents of Thendal Grove, surviving this depletion requires securing every possible reserve of raw energy.",sp=0},{t="The Value of Windstones",b="Windstones are vibrant blue crystalline formations scattered naturally throughout Thendal Grove. Within their brittle shells lies dense, concentrated wind magic left behind from ages past. While not an endless solution, they provide a reliable and invaluable source of arcane sustenance and utility for the island's elves, making the collection of raw clusters a vital daily endeavor.",sp=0}},faq={{q="What are windstones?",a="Windstones are blue crystalline deposits found around Thendal Grove that contain concentrated, raw wind energy. The elves of Zephras Isle harvest them as an essential magical fuel source.",al={"raw windstone","windstone cluster","blue crystals"}},{q="Who is Dalia the Collector?",a="Dalia is an elven collector stationed in Thendal Grove on Zephras Isle. She organizes the gathering of vital raw resources, particularly windstones, to help support the island's dwindling magical reserves.",al={"dalia","dalia zephras","collector dalia"}},{q="Why is the magic on Zephras Isle fading?",a="Centuries ago, the wind elementals that lived alongside the local elves vanished. Without their ongoing presence, the enchantment imbued into the island by the great anchor pylons has been slowly draining away.",al={"zephras losing magic","fading magic zephras","anchor pylons"}},{q="Where did the wind elementals go?",a="Their exact fate remains a mystery. All that is known is that they vanished several centuries ago, leaving the island to slowly exhaust its remaining elemental reserves.",al={"missing elementals","where are wind elementals","elementals vanished"}},{q="What are the anchor pylons?",a="The great anchor pylons are ancient structures on Zephras Isle imbued with powerful magic to sustain the land. With the elementals gone, their sustaining energies are gradually weakening.",al={"great anchor pylons","anchor pylon lore"}},{q="Where do you find raw windstones?",a="Raw windstones can be found scattered across the landscape throughout Thendal Grove on Zephras Isle, appearing as glowing blue crystalline outcrops.",al={"windstone location","thendal grove crystals"}}},ang={["class:Mage"]="For practitioners of the arcane, the concentrated elemental power within windstones offers a stark reminder of how fragile magical ecosystems become when their elemental sources vanish.",["profession:Mining"]="Harvesting raw windstones is an introduction to gathering valuable minerals and crystals from the untamed wilds of Zephras Isle."},kw={"anchor pylons","dalia","dalia the collector","thendal grove","wind elementals","windstone cluster","windstones","zephras isle"},rel={"zone:zephras"},m={start="Dalia the Collector",level="4",id=93552},src={"Harvesting Windstones"},fv=true}
E["quest:93746"] = {t="quest",n="A Firm Response",z="zephras",s="\"A Firm Response\" is a Horde quest on Zephras Isle issued by Ayessa Dawnsinger. Tensions are boiling over as the mysterious High Order intrudes upon the territory and dealings of the local Windshapers. Ayessa orders a preemptive strike against Belathaan Brightwish on the road to the Shrine of Akir to establish clear boundaries through force.",h="\"A Firm Response\" is a Horde quest on Zephras Isle issued by Ayessa Dawnsinger.",sec={{t="Drawing the Line",b="The Windshapers of Zephras Isle do not tolerate uninvited scrutiny, especially from an organization as secretive and calculating as the High Order. Prior warnings have gone unheeded, forcing Ayessa Dawnsinger to escalate the matter. To safeguard their interests, she chooses to intercept Belathaan Brightwish in the isolated stretch of road leading north toward the Shrine of Akir, ensuring the altercation stays away from prying eyes in town.",sp=0},{t="Storms on the Road",b="Belathaan's excursion north toward the ancient Shrine of Akir raises immediate suspicion, though his exact motives remain unclear. When confronted on the secluded road, the encounter quickly turns hostile, drawing Living Storms into the fray. Defeating these turbulent elementals and humbling Belathaan sends an unmistakable message back to the High Order: interference with the Windshapers will be answered with force.",sp=1}},faq={{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger is a questgiver aligned with the Horde and the Windshapers on Zephras Isle. She is protective of their domain and ruthless when handling intruders who meddle in their affairs.",al={"ayessa dawnsinger","who gives a firm response","ayessa"}},{q="Who is Belathaan Brightwish?",a="Belathaan Brightwish is an operative tied to the High Order. He is spotted heading alone toward the Shrine of Akir and becomes the target of Ayessa Dawnsinger's attempt to intimidate his organization.",al={"belathaan brightwish","belthaan","who is belathaan"}},{q="What is the High Order?",a="The High Order is a faction operating on Zephras Isle whose activities run counter to the local Windshapers. Despite explicit warnings, they continue probing into affairs that do not belong to them.",al={"high order","the high order lore","what is the high order"}},{q="Where is the Shrine of Akir located?",a="The Shrine of Akir lies to the north of town on Zephras Isle. Belathaan is intercepted along the secluded road leading toward this landmark.",al={"shrine of akir","where is shrine of akir","shrine akir zephras"}},{q="Why does Ayessa want Belathaan beaten rather than killed?",a="Ayessa explicitly aims to send a message rather than start a total war. By battering Belathaan and allowing him to return to his superiors, she hopes to instill fear and respect for the Windshapers' boundaries.",al={"kill belathaan","why spare belathaan","why just bruises"}},{q="What are the Living Storms encountered during this task?",a="Living Storms are elemental entities that manifest during the confrontation with Belathaan on the road, reflecting the volatile elemental energies that define Zephras Isle.",al={"living storms","what are living storms"}}},ang={["faction:Horde"]="The Horde's presence on Zephras Isle relies on establishing secure positions and keeping rival factions like the High Order from encroaching on allied interests.",["class:Shaman"]="The clash with Living Storms on the road highlights the turbulent, untamed elemental air magic pervasive throughout Zephras Isle."},kw={"a firm response","ayessa dawnsinger","belathaan brightwish","high order","living storms","shrine of akir","windshapers","zephras isle"},rel={"npc:ayessa-dawnsinger","zone:zephras"},m={start="Ayessa Dawnsinger",level="9",faction="Horde",id=93746},src={"A Firm Response"},fv=true}
E["quest:94414"] = {t="quest",n="The Anchors of Zephras",z="zephras",s="The Anchors of Zephras is an introductory quest offered by Halaan Hawk-Eye on Zephras Isle. Halaan invites travelers to borrow his far-reaching vision to observe the ancient anchor pylons that tether and preserve the floating island. Though the soaring monoliths appear untouched from a distance, Halaan warns that the wind spirits' stabilizing magic has begun to waver.",h="The Anchors of Zephras is an introductory quest offered by Halaan Hawk-Eye on Zephras Isle.",sec={{t="Tethers of the Isle",b="The anchor pylons of Zephras are ancient, towering monoliths gifted by the spirits of the winds. Deeply woven into the isle's mystical foundation, they serve to bind, steady, and sustain the landmass amidst the churning skies. To look upon one is to witness the fragile balance keeping Zephras aloft, relying continuously on the benevolence of the wind spirits and the subterranean flows of the world.",sp=0},{t="A Disturbing Shift",b="Despite standing proud and undamaged to the naked eye, the anchor pylons have grown erratic. Halaan Hawk-Eye notes that the magical harmony sustaining them has become unstable and inconsistent in recent times. Without clear signs of physical distress, this subtle decay raises quiet alarm among those who watch over the groves, hinting at deeper imbalances threatening the isle.",sp=0},{t="Halaan's Gift",b="Lacking the innate skysight that peers across worlds or the arcane prowess to tap Zephras's deep ley lines, Halaan possesses a simpler, sharper natural gift: keen, unclouded vision over immense distances. By lending this perspective, he allows others to observe the distant pylons in fine detail, encouraging newcomers to cultivate gratitude for the present while staying alert to their homeland's shifting fate.",sp=0}},faq={{q="What are the anchor pylons on Zephras?",a="The anchor pylons are ancient mystical structures bestowed by the spirits of the winds. They bind, anchor, and magically sustain the island of Zephras, keeping it stable above the surrounding world.",al={"what are the anchors","zephras anchor pylon","what is an anchor pylon"}},{q="What is wrong with the anchor pylons?",a="While the pylons show no obvious physical damage or external decay, their stabilizing magic has recently turned unstable and inconsistent, sparking concern about what is quietly disrupting their bond.",al={"why are anchors failing","anchor pylon problem","what happened to the anchors"}},{q="Who is Halaan Hawk-Eye?",a="Halaan Hawk-Eye is a watcher residing in the groves of Zephras Isle. Blessed with sharp, far-reaching natural eyesight, he monitors the health of the land and ponders the island's mystical well-being.",al={"halaan lore","who is halaan"}},{q="What is Halaan's gift?",a="Halaan's gift is exceptionally acute long-distance sight. Unlike mystics who wield skysight to peer between worlds or channel ley line energies, Halaan's power is natural and mundane, allowing him to perceive distant landmarks with pristine clarity.",al={"halaan's gift","how does halaan see far"}},{q="What is skysight?",a="Skysight is a mystical perception possessed by certain practitioners on Zephras that allows them to pierce the veil and peer directly between worlds, far surpassing ordinary physical vision.",al={"what is the skysight","skysight meaning"}},{q="Where does the magic powering the pylons come from?",a="The anchor pylons were granted to Zephras by the spirits of the winds. Their ambient power is tied closely to these wind spirits as well as the latent magical ley lines running beneath the isle.",al={"who made the pylons","anchor pylon origin"}}},ang={["class:Shaman"]="The anchor pylons rely directly on the blessing of the wind spirits, making any instability in their magic an urgent elemental matter for shamans seeking to maintain balance.",["class:Mage"]="While the anchors are elemental in origin, their reliance on the ley lines beneath Zephras indicates an intricate convergence of raw arcane conduits and atmospheric power."},kw={"anchor pylon","anchors of zephras","halaan hawk-eye","ley lines","skysight","wind spirits","zephras"},rel={"npc:halaan-hawk-eye","zone:zephras"},m={start="Halaan Hawk-Eye",level="2",id=94414},src={"The Anchors of Zephras"},fv=true}
E["quest:96638"] = {t="quest",n="The Adventurer",z="zephras",s="\"The Adventurer\" is an introductory journey quest on Zephras Isle. Given by Aetheen of the Gales in Thendal Grove, it directs newly seasoned wanderers southwest toward Shen'dar Village to meet Raan Wildwind, a veteran camper who knows the wilds.",h="\"The Adventurer\" is an introductory journey quest on Zephras Isle.",sec={{t="Leaving the Grove",b="While Thendal Grove provides shelter and quiet refuge, the wider expanses of Zephras Isle remain wild and perilous. Aetheen of the Gales watches over the initiates and sees when an aspiring traveler is ready to step beyond familiar borders. For those seeking fame, fortune, or purpose, remaining behind the grove's sheltered perimeter is no longer enough.",sp=0},{t="A Guide on the Road",b="Southwest of the grove along the road toward Shen'dar Village, another traveler has already made his camp. Raan Wildwind has spent time navigating the perils outside the safe haven. Seeking him out provides burgeoning wanderers a pragmatic introduction to survival beyond Thendal Grove, learning from someone who has already braved the open paths.",sp=0}},faq={{q="Who sends you to find Raan Wildwind?",a="Aetheen of the Gales gives the quest within Thendal Grove. After you prove yourself in the surrounding woods, she encourages you to seek out someone with firsthand experience of the wider isle.",al={"who gives the adventurer","who starts the adventurer quest","aetheen quest"}},{q="Where is Raan Wildwind located?",a="Raan Wildwind has set up camp southwest of Thendal Grove, situated right along the main road leading toward Shen'dar Village.",al={"raan wildwind location","where is raan","how to find raan wildwind"}},{q="What is the purpose of this task?",a="It serves as a breadcrumb guide, transitioning travelers out of the safe haven of Thendal Grove and connecting them with mentors and challenges deeper into Zephras Isle.",al={"why do the adventurer","purpose of quest the adventurer","what does raan teach"}},{q="What prerequisite must be completed before receiving this quest?",a="You must complete the task concerning the Foul Matriarch for Aetheen of the Gales before she directs you down the road to Raan Wildwind.",al={"the adventurer prereq","requirements for the adventurer"}},{q="Is Shen'dar Village safe for travelers?",a="Shen'dar Village lies further southwest past Raan's encampment. While it marks a notable settlement on the isle, the roads and surrounding wilds require caution from young adventurers.",al={"is shendar safe","what is shendar village"}},{q="Who is Raan Wildwind?",a="Raan Wildwind is an adventurous wanderer who ventured beyond Thendal Grove to establish a camp outside Shen'dar Village, offering advice and tasks to newcomers heading down the road.",al={"raan lore","who is raan wildwind"}}},ang={["race:Skyborne"]="For young Skyborne emerging from the sheltered canopy of Thendal Grove, meeting Raan Wildwind marks the first true step into the broader, untamed geography of their island home."},kw={"aetheen of the gales","raan wildwind","shen'dar village","the adventurer","thendal grove","zephras isle"},rel={"quest:92470","quest:92471","zone:zephras"},m={start="Aetheen of the Gales",["end"]="Raan Wildwind",level="6",id=96638},src={"The Adventurer (Zephras Isle)"},fv=true}
E["subzone:calmbreeze-inn"] = {t="subzone",n="Calmbreeze Inn",z="zephras",s="Calmbreeze Inn refers to the primary establishments offering shelter and services across Zephras Isle, found in both Shen'dar Village and Valaanar. They serve as essential rest stops for travelers exploring the island, housing local trade trainers, innkeepers, and historical artifacts.",h="Calmbreeze Inn refers to the primary establishments offering shelter and services across Zephras Isle, found...",sec={{t="Rest on the Isle",b="The Calmbreeze Inns provide sanctuary amid the winding trails of Zephras Isle. In Shen'dar Village, the inn operates under Coriella Calmbreeze and doubles as a central hub where island tradesfolk gather, including mentors in herbalism, skinning, and enchanting. Across the way in Valaanar, another Calmbreeze Inn accommodates local wayfarers and shelters rare curios, including an audio crystal recording the history of the ancient rebellion in Eldre'Thalas.",sp=0}},faq={{q="Where are the Calmbreeze Inns located?",a="Calmbreeze Inn locations can be found in both Shen'dar Village and Valaanar on Zephras Isle.",al={"calmbreeze inn location","where is calmbreeze inn","calmbreeze inn map"}},{q="Who runs the inn in Shen'dar Village?",a="The Shen'dar Village location is maintained by Innkeeper Coriella Calmbreeze, offering hospitality to island residents and travelers alike.",al={"calmbreeze innkeeper","who runs calmbreeze inn"}},{q="What trainers can be found at the inn?",a="In Shen'dar Village, the inn houses Halassa Fernbreeze for Herbalism, Mendalass Tattermend for Skinning, Nasalanna Windsinger for Enchanting, and Miriann Mistblade for Rogue training.",al={"calmbreeze trainers","shen'dar inn trainers"}},{q="What is the audio crystal found upstairs in Valaanar?",a="Upstairs in the Valaanar inn rests an audio crystal containing Part 3 of 'The Rebellion In Eldre'Thalas', chronicling historic events from the ancient Highborne city.",al={"valaanar audio crystal","the rebellion in eldre'thalas crystal"}}},ang={["profession:Herbalism"]="Herbalists visiting Shen'dar Village can seek out Halassa Fernbreeze inside the Calmbreeze Inn to hone their gathering craft.",["class:Rogue"]="Miriann Mistblade offers rogue instruction from the hearth of the Shen'dar Village Calmbreeze Inn."},kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","shen'dar village","valaanar","zephras isle"},rel={"zone:zephras"},src={"Calmbreeze Inn"}}
E["zone:zephras"] = {t="zone",n="Zephras Isle",z="zephras",s="Zephras Isle is a flying island suspended within Skywall, the Elemental Plane of air. It serves as the ancestral starting home of the Skyborne, whose society now faces an existential crisis as the island's sustaining magic steadily erodes. With contact severed from neighboring sky-realms, its inhabitants struggle against elemental collapse and arriving refugees.",h="Zephras Isle is a flying island suspended within Skywall, the Elemental Plane of air.",sec={{t="A Realm Aloft",b="Zephras Isle is an isolated landmass adrift in the endless winds of Skywall. For generations, the Skyborne lived here alongside native air elementals who helped preserve the magical currents holding the isle aloft. However, several centuries ago, those elemental stewards vanished entirely. Deprived of their presence and guardianship, the latent enchantments upholding the land have slowly begun to fail, causing Zephras to slowly fracture and destabilize.",sp=0},{t="Severed Horizons",b="Zephras was not the only sanctuary inhabited by the Skyborne within the Elemental Plane. Sister islands known as Anvilas and Siroccas also drifted across Skywall, but communications between them ceased after the elementals vanished. In recent times, refugees from these crumbling neighboring landmasses have managed to reach Zephras seeking safety, bearing grim tidings that the other islands are disintegrating outright beneath their feet.",sp=0},{t="Threshold to Azeroth",b="With their own landmass in slow decay, the Skyborne of Zephras have begun looking beyond the boundaries of Skywall toward Azeroth. From the skydocks of Valanaar, airships now venture forth to establish rare lifelines to the mortal realm. These voyages connect the airy domain directly to points on Azeroth, including the outskirts of Dalaran in the Alterac Mountains and the Skywatcher Plateau in Mulgore.",sp=0}},faq={{q="Where is Zephras Isle located?",a="Zephras Isle is situated inside Skywall, the Elemental Plane of air, rather than upon the surface of Azeroth. It floats among the perpetual clouds and wind currents of this ethereal domain.",al={"zephras isle location","where is zephras","what plane is zephras on"}},{q="Why is Zephras Isle falling apart?",a="The island relied on the presence of native air elementals who once coexisted with the Skyborne. Several centuries ago, these elementals vanished, leaving the magical foundations that anchor and preserve the flying land to slowly weaken and decay over time.",al={"why is zephras collapsing","zephras isle destruction","dying island"}},{q="What are Anvilas and Siroccas?",a="They are neighboring floating islands in Skywall also populated by the Skyborne. Zephras Isle lost communication with both when the elementals disappeared, and fleeing refugees now report that both Anvilas and Siroccas are collapsing into oblivion.",al={"anvilas","siroccas","other skyborne islands"}},{q="How do people travel between Zephras Isle and Azeroth?",a="The Skyborne operate skydocks at the settlement of Valanaar. Airships launch from these docks across the planar boundary to Azeroth, landing near Dalaran in the Alterac Mountains and at Skywatcher Plateau in Mulgore.",al={"how to leave zephras","zephras airships","travel to azeroth"}},{q="Who are the Skyborne?",a="The Skyborne are the inhabitants who make their home on Zephras Isle and its sister sky-realms. Having dwelled in Skywall for generations, they now face the slow destruction of their flying homeland as its binding magic fades.",al={"skyborne race","who lives on zephras"}},{q="Who lives on Zephras Isle besides the Skyborne?",a="Aside from peaceful villages and visiting refugees, the island is troubled by local bandits, cavern-dwelling nightclaws, and beasts inhabiting areas like the Shriekling Den and Nightclaw Cavern.",al={"zephras inhabitants","enemies on zephras"}}},ang={["race:Skyborne"]="Zephras Isle is your ancestral home and starting ground, though its lingering beauty masks an urgent crisis of collapsing terrain and fading elemental power.",["class:Shaman"]="Existing directly within the Elemental Plane of air, Zephras Isle showcases what happens to elemental lands when the spirits that balance them suddenly disappear."},kw={"airships","anvilas","elemental plane","siroccas","skyborne","skywall","valanaar","windstones","zephras"},rel={"topic:skyborne","topic:skywall","topic:elemental-plane","npc:ventaari-brightwish","quest:93552","zone:alterac","zone:mulgore","subzone:dalaran"},m={levels="1-10"},src={"Zephras Isle"}}
